def main():
    output = Path(sys.argv[1]).resolve()
    output.mkdir(parents=True, exist_ok=True)
    candidates = [Path(os.environ.get('TNR_FONT_DIR', '/System/Library/Fonts/Supplemental')),
                  Path('C:/Windows/Fonts'), Path('/usr/share/fonts/truetype/msttcorefonts')]
    font_dir = next((p for p in candidates if (p/'Times New Roman.ttf').exists() or (p/'times.ttf').exists()), None)
    if font_dir is None:
        raise RuntimeError('Install licensed Times New Roman and set TNR_FONT_DIR. Font substitution is not allowed.')
    regular = font_dir/('Times New Roman.ttf' if (font_dir/'Times New Roman.ttf').exists() else 'times.ttf')
    bold = font_dir/('Times New Roman Bold.ttf' if (font_dir/'Times New Roman Bold.ttf').exists() else 'timesbd.ttf')
    pdfmetrics.registerFont(TTFont('TNR', str(regular)))
    pdfmetrics.registerFont(TTFont('TNR-Bold', str(bold)))
    body = ParagraphStyle('body', fontName='TNR', fontSize=14, leading=21, alignment=TA_JUSTIFY, spaceAfter=7)
    heading = ParagraphStyle('heading', parent=body, fontName='TNR-Bold', spaceAfter=14, keepWithNext=True)
    width, height = A4
    margin = 30*mm
    results = []
    for filename, maximum, pages in DOCUMENTS:
        target = output/filename
        doc = BaseDocTemplate(str(target), pagesize=A4, leftMargin=margin, rightMargin=margin,
            topMargin=margin, bottomMargin=margin, title=filename[3:-4], author='Команда проекта «Мост между нами»')
        frame = Frame(margin,margin,width-2*margin,height-2*margin,leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)
        doc.addPageTemplates(PageTemplate(id='competition',frames=[frame]))
        story=[]
        for i,page in enumerate(pages):
            if i:story.append(PageBreak())
            for text,is_heading in page:
                story.append(Paragraph(text.replace('&','&amp;').replace('<','&lt;'),heading if is_heading else body))
        doc.build(story)
        reader=PdfReader(target)
        if len(reader.pages)>maximum or len(reader.pages)!=len(pages):
            raise AssertionError(f'{filename}: unexpected pagination {len(reader.pages)}; expected {len(pages)}')
        fonts=set()
        with pdfplumber.open(target) as pdf:
            for page in pdf.pages:
                assert abs(page.width-width)<1 and abs(page.height-height)<1
                for char in page.chars:
                    fonts.add(char['fontname'])
                    assert abs(char['size']-14)<.1
                    assert char['x0']>=margin-.5 and char['x1']<=width-margin+.5
                    assert char['top']>=margin-.5 and char['bottom']<=height-margin+.5
        assert all('TimesNewRoman' in name for name in fonts),fonts
        results.append({'file':filename,'pages':len(reader.pages),'limit':maximum,'fonts':sorted(fonts),
            'fontSize':14,'leading':21,'alignment':'justify','marginsMm':[30,30,30,30],'bytes':target.stat().st_size})
    (output/'pdf-verification.json').write_text(json.dumps(results,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps(results,ensure_ascii=False,indent=2))

if __name__=='__main__':main()
